                    return (int)Ingestible_FieldIndex.DNAM;
                }
                case RecordTypeInts.MIID:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.MIID = frame.ReadUInt32();
                    return (int)Ingestible_FieldIndex.MIID;
                }
                case RecordTypeInts.EFID:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.BaseEffect.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Ingestible_FieldIndex.BaseEffect;
                }
                case RecordTypeInts.EFIT:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.EFIT = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Ingestible_FieldIndex.EFIT;
                }
                case RecordTypeInts.ENIT:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.ENIT = ByteArrayBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Ingestible_FieldIndex.ENIT;
                }
                case RecordTypeInts.CODV:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.CODV = frame.ReadUInt32();
                    return (int)Ingestible_FieldIndex.CODV;
                }
                case RecordTypeInts.CTDA:
                case RecordTypeInts.CITC:
                {
                    item.Conditions = 
                        Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<Condition>.Instance.ParsePerItem(
                            reader: frame,
                            countLengthLength: 4,
                            countRecord: RecordTypes.CITC,
                            triggeringRecord: Condition_Registration.TriggerSpecs,
                            translationParams: translationParams,
                            transl: Condition.TryCreateFromBinary)
                        .CastExtendedList<Condition>();
                    return (int)Ingestible_FieldIndex.Conditions;
                }
                case RecordTypeInts.CVT0:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.CVT0 = StringBinaryTranslation.Instance.Parse(
                        reader: frame.SpawnWithLength(contentLength),
                        stringBinaryType: StringBinaryType.NullTerminate,
                        parseWhole: true);
                    return (int)Ingestible_FieldIndex.CVT0;
                }
                case RecordTypeInts.DURG:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.DURG = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Ingestible_FieldIndex.DURG;
                }
                case RecordTypeInts.MAGF:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.MAGF = frame.ReadUInt32();
                    return (int)Ingestible_FieldIndex.MAGF;
                }
                case RecordTypeInts.MAGG:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.MAGG.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Ingestible_FieldIndex.MAGG;
                }
                default:
                    return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                        item: item,
                        frame: frame,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        nextRecordType: nextRecordType,
                        contentLength: contentLength,
                        translationParams: translationParams.WithNoConverter());
            }
